WebLink.url:
{!REQUIRESCRIPT('/soap/ajax/27.0/connection.js')}



var selected = '{!Case.Account}';

if (selected[0] == null) { 

    alert("Please select the Account Name")
} 

else {

var caseObj = new sforce.SObject("Case");
caseObj.Id = '{!Case.Id}';
caseObj.Status = 'Closed - Approved';
var result = sforce.connection.update([caseObj]);

var newOpp = new sforce.SObject('Opportunity');
newOpp.AccountId = '{!Case.AccountId}';
newOpp.Name = '{!Case.Subject}';
newOpp.StageName = 'Prospecting';
newOpp.CloseDate = new Date();
newOpp.Description ='{!JSENCODE(Case.Description)}'; 



var result = sforce.connection.query("Select Id, Name From RecordType Where SobjectType = 'Opportunity' AND Name = 'Adhoc Charter'");
var records = result.getArray("records");
newOpp.RecordtypeId = records[0].Id;



var result = sforce.connection.create([newOpp]);

if(result[0].success=='true'){
    alert('Opportunity has been Created Successfully.');
    window.location = '/' + result[0].id;
}
}
